with filtered as (select *, case when account_type = 'SAVINGS' then 1 else 0 end is_savings, date_sub(opened_date, 3) opened_date_minus_3d, coalesce(status, 'NONE') status_clean from accounts where balance < 22000) select date_trunc('week', opened_date) as week_start, size(collect_set(account_type)) as num_account_types, sort_array(collect_set(account_type)) as account_type_list, count(case when account_type = 'SAVINGS' then 1 end) as savings_count from filtered group by date_trunc('week', opened_date) order by week_start asc
